INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1653','2037','analisa','[{\"langkah\":\"Persiapan pekerjaan dengan melakukan pengecekan area kerja, memastikan izin kerja telah diperoleh, serta menyiapkan APD dan peralatan yang diperlukan.\",\"bahaya\":[{\"risiko\":\"Area kerja licin atau tidak rapi sehingga berpotensi menyebabkan terpeleset atau tersandung.\",\"pengendalian\":[\"Pastikan area kerja bersih dan bebas hambatan.\",\"Bersihkan tumpahan air atau oli sebelum pekerjaan dimulai.\",\"Pasang rambu peringatan apabila terdapat potensi bahaya.\"]},{\"risiko\":\"Peralatan kerja tidak lengkap atau rusak sehingga menghambat pekerjaan.\",\"pengendalian\":[\"Periksa kelengkapan peralatan sebelum memulai pekerjaan.\",\"Ganti peralatan yang rusak atau tidak layak pakai.\",\"Gunakan peralatan sesuai fungsi dan spesifikasinya.\"]},{\"risiko\":\"Tidak menggunakan APD yang sesuai.\",\"pengendalian\":[\"Gunakan APD sesuai ketentuan perusahaan.\"]}]},{\"langkah\":\"Melakukan pemeriksaan fisik perangkat komputer, laptop, printer, dan perangkat jaringan untuk memastikan kondisi perangkat dalam keadaan baik.\",\"bahaya\":[{\"risiko\":\"Sengatan listrik akibat perangkat masih terhubung ke sumber listrik.\",\"pengendalian\":[\"Matikan perangkat dan cabut sumber listrik sebelum pemeriksaan.\",\"Pastikan tangan dalam kondisi kering.\",\"Gunakan alat yang memiliki isolasi listrik.\"]},{\"risiko\":\"Terjepit atau tergores komponen perangkat.\",\"pengendalian\":[\"Gunakan alat kerja sesuai fungsi.\",\"Ikuti prosedur pembongkaran perangkat.\",\"Hindari menyentuh komponen sensitif secara langsung.\"]},{\"risiko\":\"Kerusakan perangkat akibat penanganan yang kurang tepat.\",\"pengendalian\":[\"Tangani perangkat dengan hati-hati sesuai prosedur.\"]}]},{\"langkah\":\"Melakukan pembersihan perangkat, update sistem operasi, aplikasi, antivirus, serta pemeriksaan performa perangkat.\",\"bahaya\":[{\"risiko\":\"Debu masuk ke saluran pernapasan.\",\"pengendalian\":[\"Gunakan masker saat membersihkan perangkat.\",\"Gunakan blower dengan tekanan yang sesuai.\",\"Bersihkan perangkat di area yang memiliki ventilasi baik.\"]},{\"risiko\":\"Kesalahan konfigurasi saat proses update.\",\"pengendalian\":[\"Lakukan backup data sebelum update.\"]},{\"risiko\":\"Kehilangan data akibat kegagalan pembaruan.\",\"pengendalian\":[\"Ikuti prosedur pembaruan sesuai standar ICT.\",\"Pastikan kapasitas penyimpanan mencukupi.\",\"Jangan mematikan perangkat selama proses update berlangsung.\"]}]},{\"langkah\":\"Melakukan pengujian perangkat, dokumentasi hasil pekerjaan, dan merapikan area kerja.\",\"bahaya\":[{\"risiko\":\"Perangkat tidak berfungsi setelah pemeliharaan.\",\"pengendalian\":[\"Lakukan functional test sebelum perangkat digunakan.\",\"Periksa kembali konfigurasi sistem.\",\"Pastikan seluruh kabel telah terpasang dengan benar.\",\"Dokumentasikan hasil pengujian.\"]},{\"risiko\":\"Area kerja tidak rapi sehingga membahayakan pengguna lain.\",\"pengendalian\":[\"Rapikan seluruh peralatan setelah pekerjaan selesai.\",\"Buang sampah pada tempatnya.\",\"Pastikan tidak ada kabel atau alat yang tertinggal di area kerja.\",\"Lakukan pemeriksaan akhir sebelum meninggalkan lokasi.\"]}]}]','2026-07-21 21:14:09','2026-07-21 21:21:00');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1654','2038','analisa','[{\"langkah\":\"Persiapan pekerjaan dengan melakukan pengecekan area kerja, memastikan izin kerja telah diperoleh, serta menyiapkan APD dan peralatan yang diperlukan.\",\"bahaya\":[{\"risiko\":\"Area kerja licin atau tidak rapi sehingga berpotensi menyebabkan terpeleset atau tersandung.\",\"pengendalian\":[\"Pastikan area kerja bersih dan bebas hambatan.\",\"Bersihkan tumpahan air atau oli sebelum pekerjaan dimulai.\",\"Pasang rambu peringatan apabila terdapat potensi bahaya.\"]},{\"risiko\":\"Peralatan kerja tidak lengkap atau rusak sehingga menghambat pekerjaan.\",\"pengendalian\":[\"Periksa kelengkapan peralatan sebelum memulai pekerjaan.\",\"Ganti peralatan yang rusak atau tidak layak pakai.\",\"Gunakan peralatan sesuai fungsi dan spesifikasinya.\"]},{\"risiko\":\"Tidak menggunakan APD yang sesuai.\",\"pengendalian\":[\"Gunakan APD sesuai ketentuan perusahaan.\"]}]},{\"langkah\":\"Melakukan pemeriksaan fisik perangkat komputer, laptop, printer, dan perangkat jaringan untuk memastikan kondisi perangkat dalam keadaan baik.\",\"bahaya\":[{\"risiko\":\"Sengatan listrik akibat perangkat masih terhubung ke sumber listrik.\",\"pengendalian\":[\"Matikan perangkat dan cabut sumber listrik sebelum pemeriksaan.\",\"Pastikan tangan dalam kondisi kering.\",\"Gunakan alat yang memiliki isolasi listrik.\"]},{\"risiko\":\"Terjepit atau tergores komponen perangkat.\",\"pengendalian\":[\"Gunakan alat kerja sesuai fungsi.\",\"Ikuti prosedur pembongkaran perangkat.\",\"Hindari menyentuh komponen sensitif secara langsung.\"]},{\"risiko\":\"Kerusakan perangkat akibat penanganan yang kurang tepat.\",\"pengendalian\":[\"Tangani perangkat dengan hati-hati sesuai prosedur.\"]}]},{\"langkah\":\"Melakukan pembersihan perangkat, update sistem operasi, aplikasi, antivirus, serta pemeriksaan performa perangkat.\",\"bahaya\":[{\"risiko\":\"Debu masuk ke saluran pernapasan.\",\"pengendalian\":[\"Gunakan masker saat membersihkan perangkat.\",\"Gunakan blower dengan tekanan yang sesuai.\",\"Bersihkan perangkat di area yang memiliki ventilasi baik.\"]},{\"risiko\":\"Kesalahan konfigurasi saat proses update.\",\"pengendalian\":[\"Lakukan backup data sebelum update.\"]},{\"risiko\":\"Kehilangan data akibat kegagalan pembaruan.\",\"pengendalian\":[\"Ikuti prosedur pembaruan sesuai standar ICT.\",\"Pastikan kapasitas penyimpanan mencukupi.\",\"Jangan mematikan perangkat selama proses update berlangsung.\"]}]},{\"langkah\":\"Melakukan pengujian perangkat, dokumentasi hasil pekerjaan, dan merapikan area kerja.\",\"bahaya\":[{\"risiko\":\"Perangkat tidak berfungsi setelah pemeliharaan.\",\"pengendalian\":[\"Lakukan functional test sebelum perangkat digunakan.\",\"Periksa kembali konfigurasi sistem.\",\"Pastikan seluruh kabel telah terpasang dengan benar.\",\"Dokumentasikan hasil pengujian.\"]},{\"risiko\":\"Area kerja tidak rapi sehingga membahayakan pengguna lain.\",\"pengendalian\":[\"Rapikan seluruh peralatan setelah pekerjaan selesai.\",\"Buang sampah pada tempatnya.\",\"Pastikan tidak ada kabel atau alat yang tertinggal di area kerja.\",\"Lakukan pemeriksaan akhir sebelum meninggalkan lokasi.\"]}]}]','2026-07-21 21:35:15','2026-07-21 21:35:15');
