INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1659','2038','catatan_revisi','[{\"no_rev\":1,\"tanggal\":\"2026-07-21\",\"halaman\":\"1\",\"catatan\":\"Penambahan Lokasi Kerja\"}]','2026-07-21 21:41:18','2026-07-21 21:41:29');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1660','2039','tujuan','[\"Menetapkan tata cara pelaksanaan proses handover perangkat, pekerjaan, maupun dokumen agar berjalan tertib, terdokumentasi, dan dapat dipertanggungjawabkan.\",\"Memastikan seluruh aset, informasi, dan tanggung jawab telah diserahkan secara lengkap kepada pihak penerima.\",\"Mencegah terjadinya kehilangan aset, informasi, maupun kesalahan operasional akibat proses serah terima yang tidak terdokumentasi.\",\"Menjamin adanya bukti administrasi atas setiap proses handover yang dilakukan.\"]','2026-07-21 22:31:09','2026-07-21 22:31:23');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1661','2039','ruang_lingkup','[\"SOP ini berlaku untuk seluruh proses handover perangkat IT, dokumen, akun sistem, dan pekerjaan yang dikelola oleh Departemen ICT.\",\"SOP ini diterapkan pada kegiatan serah terima antar personel, antar shift, maupun pada saat mutasi, cuti panjang, resign, atau pergantian PIC.\",\"SOP ini mencakup proses persiapan, pemeriksaan, verifikasi, dokumentasi, hingga persetujuan handover.\",\"SOP ini berlaku bagi seluruh karyawan, kontraktor, maupun pihak ketiga yang terlibat dalam proses handover.\"]','2026-07-21 22:31:09','2026-07-21 22:31:56');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1662','2039','referensi','[\"Kebijakan Pengelolaan Aset Teknologi Informasi PT PPA\",\"Standar Operasional Departemen ICT mengenai Manajemen Aset IT.\",\"Peraturan Perusahaan terkait Pengelolaan Dokumen dan Serah Terima Aset.\",\"ISO 9001:2015 \\u2013 Quality Management System.\",\"ISO\\/IEC 27001 \\u2013 Information Security Management System.\"]','2026-07-21 22:31:09','2026-07-21 22:32:30');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1663','2039','definisi','[\"Handover adalah proses serah terima aset, dokumen, pekerjaan, atau tanggung jawab dari pihak pemberi kepada pihak penerima yang dibuktikan melalui dokumen resmi.\",\"Pemberi Handover adalah personel yang menyerahkan aset, dokumen, pekerjaan, atau tanggung jawab kepada pihak lain.\",\"Penerima Handover adalah personel yang menerima aset, dokumen, pekerjaan, atau tanggung jawab serta bertanggung jawab atas pengelolaannya setelah proses serah terima selesai.\",\"Checklist Handover adalah daftar pemeriksaan yang digunakan untuk memastikan seluruh item yang diserahterimakan telah lengkap dan sesuai.\",\"Berita Acara Serah Terima (BAST) adalah dokumen resmi yang menjadi bukti telah dilaksanakannya proses handover antara kedua belah pihak.\"]','2026-07-21 22:31:09','2026-07-21 22:32:59');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1664','2039','aktivitas','[{\"sub_judul\":\"Persiapan Handover\",\"deskripsi\":\"Pemberi handover menyiapkan seluruh aset, dokumen, akun, serta informasi pekerjaan yang akan diserahterimakan dan memastikan seluruh data telah lengkap.\",\"pic\":\"ICT\"},{\"sub_judul\":\"Pemeriksaan Kelengkapan\",\"deskripsi\":\"Melakukan pemeriksaan terhadap aset, dokumen, akun, lisensi, maupun pekerjaan yang akan diserahterimakan berdasarkan checklist handover.\",\"pic\":\"Pemberi Handover \\/ Penerima Handover\"},{\"sub_judul\":\"Pelaksanaan Handover\",\"deskripsi\":\"Melaksanakan proses serah terima aset, pekerjaan, dan informasi kepada penerima serta memberikan penjelasan mengenai kondisi dan status pekerjaan.\",\"pic\":\"Pemberi Handover\"},{\"sub_judul\":\"Verifikasi Hasil Handover\",\"deskripsi\":\"Penerima melakukan verifikasi terhadap seluruh aset, dokumen, maupun pekerjaan yang diterima untuk memastikan kesesuaian dengan checklist handover.\",\"pic\":\"Penerima Handover\"},{\"sub_judul\":\"Dokumentasi dan Persetujuan\",\"deskripsi\":\"Mengisi Berita Acara Serah Terima (BAST), memperoleh tanda tangan pihak terkait, serta mengarsipkan dokumen handover sebagai bukti administrasi.\",\"pic\":\"Admin ICT \\/ Document Control\"},{\"sub_judul\":\"Penutupan Proses Handover\",\"deskripsi\":\"Melakukan pembaruan data inventaris, penyesuaian hak akses apabila diperlukan, serta menyatakan proses handover telah selesai.\",\"pic\":\"ICT Administrator\"}]','2026-07-21 22:33:55','2026-07-21 22:38:06');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1665','2039','lampiran','[{\"judul\":\"Form Checklist Handover\",\"keterangan\":\"Daftar pemeriksaan yang digunakan untuk memastikan seluruh aset, dokumen, akun, dan pekerjaan telah diserahterimakan secara lengkap.\",\"gambar\":null},{\"judul\":\"Berita Acara Serah Terima (BAST)\",\"keterangan\":\"Dokumen resmi yang berisi informasi proses handover serta ditandatangani oleh pemberi, penerima, dan pihak yang berwenang sebagai bukti serah terima.\",\"gambar\":null},{\"judul\":\"Daftar Inventaris Aset\",\"keterangan\":\"Daftar aset yang diserahterimakan, meliputi nama aset, nomor inventaris, kondisi aset, dan keterangan lainnya.\",\"gambar\":null},{\"judul\":\"Dokumentasi Foto Handover\",\"keterangan\":\"Dokumentasi berupa foto yang menunjukkan proses serah terima aset atau pekerjaan sebagai bukti pelaksanaan handover.\",\"gambar\":null}]','2026-07-21 22:33:55','2026-07-21 22:38:48');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1818','2182','analisa','[{\"langkah\":\"Persiapan pekerjaan dengan melakukan pengecekan area kerja, memastikan izin kerja telah diperoleh, serta menyiapkan APD dan peralatan yang diperlukan.\",\"bahaya\":[{\"risiko\":\"Area kerja licin atau tidak rapi sehingga berpotensi menyebabkan terpeleset atau tersandung.\",\"pengendalian\":[\"Pastikan area kerja bersih dan bebas hambatan.\",\"Bersihkan tumpahan air atau oli sebelum pekerjaan dimulai.\",\"Pasang rambu peringatan apabila terdapat potensi bahaya.\"]},{\"risiko\":\"Peralatan kerja tidak lengkap atau rusak sehingga menghambat pekerjaan.\",\"pengendalian\":[\"Periksa kelengkapan peralatan sebelum memulai pekerjaan dan pastikan mengganti peralatan yang rusak atau tidak layak pakai, sehingga akan di gunakan peralatan yang sesuai fungsi dan spesifikasinya\",\"Ganti peralatan yang rusak atau tidak layak pakai.\",\"Gunakan peralatan sesuai fungsi dan spesifikasinya.\"]},{\"risiko\":\"Tidak menggunakan APD yang sesuai.\",\"pengendalian\":[\"Gunakan APD sesuai ketentuan perusahaan.\"]}]},{\"langkah\":\"Melakukan pemeriksaan fisik perangkat komputer, laptop, printer, dan perangkat jaringan untuk memastikan kondisi perangkat dalam keadaan baik.\",\"bahaya\":[{\"risiko\":\"Sengatan listrik akibat perangkat masih terhubung ke sumber listrik.\",\"pengendalian\":[\"Matikan perangkat dan cabut sumber listrik sebelum pemeriksaan.\",\"Pastikan tangan dalam kondisi kering.\",\"Gunakan alat yang memiliki isolasi listrik.\"]},{\"risiko\":\"Terjepit atau tergores komponen perangkat.\",\"pengendalian\":[\"Gunakan alat kerja sesuai fungsi.\",\"Ikuti prosedur pembongkaran perangkat.\",\"Hindari menyentuh komponen sensitif secara langsung.\"]},{\"risiko\":\"Kerusakan perangkat akibat penanganan yang kurang tepat.\",\"pengendalian\":[\"Tangani perangkat dengan hati-hati sesuai prosedur.\"]}]},{\"langkah\":\"Melakukan pembersihan perangkat, update sistem operasi, aplikasi, antivirus, serta pemeriksaan performa perangkat.\",\"bahaya\":[{\"risiko\":\"Debu masuk ke saluran pernapasan.\",\"pengendalian\":[\"Gunakan masker saat membersihkan perangkat.\",\"Gunakan blower dengan tekanan yang sesuai.\",\"Bersihkan perangkat di area yang memiliki ventilasi baik.\"]},{\"risiko\":\"Kesalahan konfigurasi saat proses update.\",\"pengendalian\":[\"Lakukan backup data sebelum update.\"]},{\"risiko\":\"Kehilangan data akibat kegagalan pembaruan.\",\"pengendalian\":[\"Ikuti prosedur pembaruan sesuai standar ICT.\",\"Pastikan kapasitas penyimpanan mencukupi.\",\"Jangan mematikan perangkat selama proses update berlangsung.\"]}]},{\"langkah\":\"Melakukan pengujian perangkat, dokumentasi hasil pekerjaan, dan merapikan area kerja.\",\"bahaya\":[{\"risiko\":\"Perangkat tidak berfungsi setelah pemeliharaan.\",\"pengendalian\":[\"Lakukan functional test sebelum perangkat digunakan.\",\"Periksa kembali konfigurasi sistem.\",\"Pastikan seluruh kabel telah terpasang dengan benar.\",\"Dokumentasikan hasil pengujian.\"]},{\"risiko\":\"Area kerja tidak rapi sehingga membahayakan pengguna lain.\",\"pengendalian\":[\"Rapikan seluruh peralatan setelah pekerjaan selesai.\",\"Buang sampah pada tempatnya.\",\"Pastikan tidak ada kabel atau alat yang tertinggal di area kerja.\",\"Lakukan pemeriksaan akhir sebelum meninggalkan lokasi.\"]}]}]','2026-07-23 08:02:12','2026-07-23 08:09:17');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1819','2182','apd','[\"Safety Helmet\",\"Safety Shoes\",\"Safety Glasses\",\"Sarung Tangan Kerja\",\"Rompi Safety\"]','2026-07-23 08:02:12','2026-07-23 08:02:12');
