INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1824','2183','aktivitas','[{\"sub_judul\":\"Persiapan Handover\",\"deskripsi\":\"Pemberi handover menyiapkan seluruh aset, dokumen, akun, serta informasi pekerjaan yang akan diserahterimakan dan memastikan seluruh data telah lengkap.\",\"pic\":\"ICT\"},{\"sub_judul\":\"Pemeriksaan Kelengkapan\",\"deskripsi\":\"Melakukan pemeriksaan terhadap aset, dokumen, akun, lisensi, maupun pekerjaan yang akan diserahterimakan berdasarkan checklist handover.\",\"pic\":\"Pemberi Handover \\/ Penerima Handover\"},{\"sub_judul\":\"Pelaksanaan Handover\",\"deskripsi\":\"Melaksanakan proses serah terima aset, pekerjaan, dan informasi kepada penerima serta memberikan penjelasan mengenai kondisi dan status pekerjaan.\",\"pic\":\"Pemberi Handover\"},{\"sub_judul\":\"Verifikasi Hasil Handover\",\"deskripsi\":\"Penerima melakukan verifikasi terhadap seluruh aset, dokumen, maupun pekerjaan yang diterima untuk memastikan kesesuaian dengan checklist handover.\",\"pic\":\"Penerima Handover\"},{\"sub_judul\":\"Dokumentasi dan Persetujuan\",\"deskripsi\":\"Mengisi Berita Acara Serah Terima (BAST), memperoleh tanda tangan pihak terkait, serta mengarsipkan dokumen handover sebagai bukti administrasi.\",\"pic\":\"Admin ICT \\/ Document Control\"},{\"sub_judul\":\"Penutupan Proses Handover\",\"deskripsi\":\"Melakukan pembaruan data inventaris, penyesuaian hak akses apabila diperlukan, serta menyatakan proses handover telah selesai.\",\"pic\":\"ICT Administrator\"}]','2026-07-23 08:02:15','2026-07-23 08:02:15');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1825','2183','definisi','[\"Handover adalah proses serah terima aset, dokumen, pekerjaan, atau tanggung jawab dari pihak pemberi kepada pihak penerima yang dibuktikan melalui dokumen resmi.\",\"Pemberi Handover adalah personel yang menyerahkan aset, dokumen, pekerjaan, atau tanggung jawab kepada pihak lain.\",\"Penerima Handover adalah personel yang menerima aset, dokumen, pekerjaan, atau tanggung jawab serta bertanggung jawab atas pengelolaannya setelah proses serah terima selesai.\",\"Checklist Handover adalah daftar pemeriksaan yang digunakan untuk memastikan seluruh item yang diserahterimakan telah lengkap dan sesuai.\",\"Berita Acara Serah Terima (BAST) adalah dokumen resmi yang menjadi bukti telah dilaksanakannya proses handover antara kedua belah pihak.\"]','2026-07-23 08:02:15','2026-07-23 08:02:15');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1826','2183','lampiran','[{\"judul\":\"Form Checklist Handover\",\"keterangan\":\"Daftar pemeriksaan yang digunakan untuk memastikan seluruh aset, dokumen, akun, dan pekerjaan telah diserahterimakan secara lengkap.\",\"gambar\":\"lampiran\\/ICTMD\\/SOP\\/img_6a615a5f085e0.png\"},{\"judul\":\"Berita Acara Serah Terima (BAST)\",\"keterangan\":\"Dokumen resmi yang berisi informasi proses handover serta ditandatangani oleh pemberi, penerima, dan pihak yang berwenang sebagai bukti serah terima.\",\"gambar\":null},{\"judul\":\"Daftar Inventaris Aset\",\"keterangan\":\"Daftar aset yang diserahterimakan, meliputi nama aset, nomor inventaris, kondisi aset, dan keterangan lainnya.\",\"gambar\":null},{\"judul\":\"Dokumentasi Foto Handover\",\"keterangan\":\"Dokumentasi berupa foto yang menunjukkan proses serah terima aset atau pekerjaan sebagai bukti pelaksanaan handover.\",\"gambar\":null}]','2026-07-23 08:02:15','2026-07-23 08:03:48');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1827','2183','referensi','[\"Kebijakan Pengelolaan Aset Teknologi Informasi PT PPA\",\"Standar Operasional Departemen ICT mengenai Manajemen Aset IT.\",\"Peraturan Perusahaan terkait Pengelolaan Dokumen dan Serah Terima Aset.\",\"ISO 9001:2015 \\u2013 Quality Management System.\",\"ISO\\/IEC 27001 \\u2013 Information Security Management System.\"]','2026-07-23 08:02:15','2026-07-23 08:02:15');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1828','2183','ruang_lingkup','[\"SOP ini berlaku untuk seluruh proses handover perangkat IT, dokumen, akun sistem, dan pekerjaan yang dikelola oleh Departemen ICT.\",\"SOP ini diterapkan pada kegiatan serah terima antar personel, antar shift, maupun pada saat mutasi, cuti panjang, resign, atau pergantian PIC.\",\"SOP ini mencakup proses persiapan, pemeriksaan, verifikasi, dokumentasi, hingga persetujuan handover.\",\"SOP ini berlaku bagi seluruh karyawan, kontraktor, maupun pihak ketiga yang terlibat dalam proses handover.\"]','2026-07-23 08:02:15','2026-07-23 08:02:15');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1829','2183','tujuan','[\"Menetapkan tata cara pelaksanaan proses handover perangkat, pekerjaan, maupun dokumen agar berjalan tertib, terdokumentasi, dan dapat dipertanggungjawabkan.\",\"Memastikan seluruh aset, informasi, dan tanggung jawab telah diserahkan secara lengkap kepada pihak penerima.\",\"Mencegah terjadinya kehilangan aset, informasi, maupun kesalahan operasional akibat proses serah terima yang tidak terdokumentasi.\",\"Menjamin adanya bukti administrasi atas setiap proses handover yang dilakukan.\"]','2026-07-23 08:02:15','2026-07-23 08:02:15');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('1830','2183','catatan_revisi','[{\"no_rev\":1,\"tanggal\":\"2026-07-23\",\"halaman\":\"3\",\"catatan\":\"Penambahan foto pada lampiran\"}]','2026-07-23 08:04:07','2026-07-23 08:08:13');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2658','2182','jsa_checklist','{\"L0-B0-P0\":\"check\",\"L0-B0-P1\":\"check\",\"L0-B0-P2\":\"check\",\"L0-B1-P0\":\"check\",\"L0-B1-P1\":\"check\",\"L0-B1-P2\":\"check\",\"L0-B2-P0\":\"check\",\"L1-B0-P0\":\"check\",\"L1-B0-P1\":\"check\",\"L1-B0-P2\":\"check\",\"L1-B1-P0\":\"check\",\"L1-B1-P1\":\"check\",\"L1-B1-P2\":\"check\",\"L1-B2-P0\":\"check\",\"L2-B0-P0\":\"check\",\"L2-B0-P1\":\"check\",\"L2-B0-P2\":\"check\",\"L2-B1-P0\":\"check\",\"L2-B2-P0\":\"check\",\"L2-B2-P1\":\"check\",\"L2-B2-P2\":\"check\",\"L3-B0-P0\":\"check\",\"L3-B0-P1\":\"check\",\"L3-B0-P2\":\"check\",\"L3-B0-P3\":\"check\",\"L3-B1-P0\":\"check\",\"L3-B1-P1\":\"check\",\"L3-B1-P2\":\"check\",\"L3-B1-P3\":\"check\"}','2026-07-24 16:30:05','2026-07-24 16:30:05');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2659','3228','tujuan','[\"Menetapkan standar pelaksanaan proses produksi agar setiap tahapan dilakukan secara konsisten, terstruktur, dan sesuai dengan ketentuan yang berlaku.\",\"Menjamin bahwa seluruh produk yang dihasilkan memiliki kualitas yang seragam serta memenuhi spesifikasi yang telah ditetapkan perusahaan.\",\"Mengurangi potensi kesalahan produksi, pemborosan bahan baku, dan waktu proses melalui penerapan prosedur kerja yang baku.\",\"Meningkatkan efisiensi penggunaan sumber daya, baik tenaga kerja, mesin, maupun material selama proses produksi berlangsung.\",\"Menjadi pedoman bagi seluruh personel produksi dalam melaksanakan tugas, melakukan pengawasan, dan mengevaluasi hasil produksi secara berkesinambungan.\"]','2026-07-25 08:43:36','2026-07-25 08:50:24');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2660','3228','ruang_lingkup','[\"Standar produksi ini berlaku untuk seluruh kegiatan produksi mulai dari penerimaan bahan baku hingga produk selesai diproses.\",\"Meliputi proses persiapan bahan, pengoperasian mesin, proses produksi, pemeriksaan kualitas, pengemasan, dan penyimpanan produk.\",\"Berlaku bagi seluruh operator produksi, teknisi, petugas quality control, kepala produksi, serta pihak lain yang terlibat dalam proses produksi.\",\"Mengatur penggunaan mesin, peralatan, bahan baku, dokumen produksi, dan formulir pemeriksaan kualitas selama proses berlangsung.\",\"Tidak mencakup kegiatan distribusi, pemasaran, maupun layanan purna jual yang diatur dalam dokumen operasional lainnya.\"]','2026-07-25 08:43:36','2026-07-25 08:51:01');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2661','3228','referensi','[\"Kebijakan Manajemen Mutu Perusahaan.\",\"Standar Operasional Prosedur (SOP) Operasional.\",\"Pedoman Sistem Manajemen Dokumen.\",\"Peraturan Perusahaan yang berlaku.\"]','2026-07-25 08:43:36','2026-07-25 08:44:49');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2662','3228','definisi','[\"Standar Produksi adalah dokumen yang berisi ketentuan, persyaratan, metode kerja, serta parameter yang digunakan sebagai pedoman dalam melaksanakan seluruh kegiatan produksi. Dokumen ini bertujuan untuk memastikan setiap proses produksi dilakukan secara konsisten, efisien, aman, dan menghasilkan produk yang memiliki kualitas sesuai dengan spesifikasi yang telah ditetapkan oleh perusahaan.\",\"Proses produksi merupakan rangkaian aktivitas yang dimulai dari penerimaan bahan baku, persiapan material, pengolahan menggunakan mesin atau peralatan, pemeriksaan kualitas, hingga proses pengemasan produk jadi. Seluruh tahapan tersebut harus dilaksanakan sesuai standar yang telah ditetapkan untuk menjaga mutu produk, efisiensi proses, serta keselamatan kerja.\",\"Bahan baku adalah seluruh material utama maupun bahan pendukung yang digunakan dalam proses produksi untuk menghasilkan suatu produk. Setiap bahan baku harus memenuhi spesifikasi kualitas, jumlah, dan kondisi yang telah ditentukan serta melalui proses pemeriksaan sebelum digunakan dalam kegiatan produksi.\",\"Quality Control (QC) adalah kegiatan pemeriksaan, pengujian, dan verifikasi terhadap bahan baku, proses produksi, maupun produk akhir untuk memastikan seluruh hasil produksi memenuhi standar mutu perusahaan. Apabila ditemukan ketidaksesuaian, petugas QC berhak memberikan rekomendasi perbaikan atau menghentikan proses produksi sampai masalah tersebut diselesaikan.\",\"Produk jadi adalah hasil akhir dari seluruh rangkaian proses produksi yang telah memenuhi persyaratan kualitas, kuantitas, fungsi, dan spesifikasi teknis sesuai standar perusahaan. Produk yang dinyatakan layak akan didokumentasikan, dikemas sesuai ketentuan, dan diserahkan ke bagian penyimpanan atau distribusi untuk proses selanjutnya.\"]','2026-07-25 08:43:36','2026-07-25 08:51:30');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2663','3228','aktivitas','[{\"sub_judul\":\"Persiapan Produksi\",\"deskripsi\":\"Melakukan pemeriksaan terhadap jadwal produksi, ketersediaan bahan baku, kondisi mesin, peralatan produksi, serta kelengkapan dokumen kerja sebelum proses produksi dimulai. Seluruh persiapan harus dipastikan sesuai dengan standar yang berlaku agar proses produksi dapat berjalan tanpa kendala.\",\"pic\":\"ICT\"},{\"sub_judul\":\"Pemeriksaan Bahan Baku\",\"deskripsi\":\"Melakukan inspeksi terhadap seluruh bahan baku yang diterima dengan memeriksa jumlah, kondisi fisik, masa simpan, dan kesesuaian spesifikasi. Bahan baku yang tidak memenuhi standar harus dipisahkan dan dilaporkan kepada bagian terkait untuk tindak lanjut.\",\"pic\":\"ICT\"},{\"sub_judul\":\"Pelaksanaan Proses Produksi\",\"deskripsi\":\"Mengoperasikan mesin dan melaksanakan proses produksi sesuai instruksi kerja, parameter mesin, serta standar operasional yang telah ditetapkan. Operator wajib mencatat setiap aktivitas produksi dan melaporkan apabila terjadi penyimpangan selama proses berlangsung.\",\"pic\":\"ICT MD\"},{\"sub_judul\":\"Pemeriksaan Kualitas Produk\",\"deskripsi\":\"Melakukan pemeriksaan terhadap produk yang sedang diproses maupun produk jadi untuk memastikan ukuran, berat, fungsi, tampilan, dan spesifikasi lainnya telah memenuhi standar mutu perusahaan. Hasil pemeriksaan didokumentasikan sebagai bagian dari rekaman mutu.\",\"pic\":\"ICT\"},{\"sub_judul\":\"Pengemasan dan Penyimpanan Produk\",\"deskripsi\":\"Produk yang telah dinyatakan memenuhi standar kualitas dikemas sesuai ketentuan perusahaan, diberi identitas produk, nomor batch, dan tanggal produksi, kemudian disimpan pada area penyimpanan sesuai prosedur agar kualitas produk tetap terjaga hingga proses distribusi.\",\"pic\":\"ICT MD\"}]','2026-07-25 08:55:05','2026-07-25 08:56:35');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2664','3228','lampiran','[{\"judul\":\"Form Pemeriksaan Bahan Baku\",\"keterangan\":\"Digunakan untuk mencatat hasil inspeksi bahan baku sebelum digunakan dalam proses produksi, meliputi jumlah, kondisi fisik, spesifikasi, dan status kelayakan.\",\"gambar\":null},{\"judul\":\"Checklist Persiapan Mesin Produksi\",\"keterangan\":\"Berisi daftar pemeriksaan kondisi mesin, kebersihan area kerja, fungsi peralatan, serta kesiapan operator sebelum produksi dimulai.\",\"gambar\":null},{\"judul\":\"Form Monitoring Produksi Harian\",\"keterangan\":\"Digunakan untuk mencatat waktu produksi, jumlah output, penggunaan bahan baku, waktu henti mesin, dan kendala yang terjadi selama proses produksi.\",\"gambar\":null},{\"judul\":\"Form Hasil Pemeriksaan Quality Control\",\"keterangan\":\"Berisi hasil pemeriksaan kualitas produk pada setiap tahap produksi beserta keputusan lulus atau tidak lulus berdasarkan standar mutu perusahaan.\",\"gambar\":null}]','2026-07-25 08:55:05','2026-07-25 08:58:04');
