INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2667','3229','aktivitas','[{\"sub_judul\":\"Persiapan Handover\",\"deskripsi\":\"Pemberi handover menyiapkan seluruh aset, dokumen, akun, serta informasi pekerjaan yang akan diserahterimakan dan memastikan seluruh data telah lengkap\",\"pic\":\"ICT\"},{\"sub_judul\":\"Pemeriksaan Kelengkapan\",\"deskripsi\":\"Melakukan pemeriksaan terhadap aset, dokumen, akun, lisensi, maupun\\r\\npekerjaan yang akan diserahterimakan berdasarkan checklist handover.\",\"pic\":\"ICT\"},{\"sub_judul\":\"Pelaksanaan Handover\",\"deskripsi\":\"Melaksanakan proses serah terima aset, pekerjaan, dan informasi kepada\\r\\npenerima serta memberikan penjelasan mengenai kondisi dan status\\r\\npekerjaan.\",\"pic\":\"ICT MD\"},{\"sub_judul\":\"Verifikasi Hasil Handover\",\"deskripsi\":\"Penerima melakukan verifikasi terhadap seluruh aset, dokumen, maupun\\r\\npekerjaan yang diterima untuk memastikan kesesuaian dengan checklist\\r\\nhandover.\",\"pic\":\"ICT\"}]','2026-07-25 09:09:44','2026-07-25 09:11:11');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2668','3229','jsa_checklist','[]','2026-07-25 09:16:49','2026-07-25 09:16:49');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2679','3232','tujuan','[\"Menetapkan tata cara pelaporan insiden secara sistematis, cepat, dan akurat agar setiap kejadian yang berhubungan dengan keselamatan, kesehatan kerja, maupun lingkungan dapat segera ditangani serta didokumentasikan dengan baik.\",\"Memastikan seluruh insiden, kecelakaan kerja, kejadian nyaris celaka (near miss), kerusakan aset, maupun kejadian yang berdampak terhadap lingkungan dilaporkan sesuai prosedur perusahaan sehingga dapat dilakukan investigasi dan tindakan perbaikan secara tepat.\",\"Meningkatkan efektivitas pengelolaan risiko melalui identifikasi penyebab insiden, analisis akar penyebab (root cause analysis), serta penerapan tindakan korektif dan tindakan pencegahan untuk mengurangi kemungkinan terulangnya kejadian serupa.\",\"Memenuhi persyaratan peraturan perundang-undangan, kebijakan perusahaan, serta standar Sistem Manajemen Keselamatan, Kesehatan Kerja, dan Lingkungan (SHE) terkait pelaporan dan investigasi insiden.\",\"Membangun budaya pelaporan yang terbuka, bertanggung jawab, dan berorientasi pada perbaikan berkelanjutan sehingga seluruh pekerja memiliki kesadaran untuk melaporkan setiap kondisi maupun tindakan yang berpotensi menimbulkan kecelakaan kerja.\"]','2026-07-25 10:30:38','2026-07-25 10:30:59');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2680','3232','ruang_lingkup','[\"SOP ini berlaku bagi seluruh karyawan perusahaan, tenaga kerja kontraktor, vendor, tamu, maupun pihak lain yang melakukan aktivitas di area operasional perusahaan.\",\"Mencakup pelaporan seluruh jenis insiden, termasuk kecelakaan kerja (Lost Time Injury), cedera ringan, kerusakan peralatan, kerusakan fasilitas, tumpahan material, pencemaran lingkungan, kebakaran, kejadian nyaris celaka (Near Miss), serta kondisi dan tindakan tidak aman (Unsafe Condition dan Unsafe Action).\",\"Berlaku untuk seluruh area operasional perusahaan, termasuk area tambang, workshop, gudang, kantor, jalan angkut (haul road), stockpile, crushing plant, disposal, jetty, dan fasilitas pendukung lainnya.\",\"Meliputi tahapan pelaporan awal, pengamanan lokasi kejadian, pemberitahuan kepada atasan, investigasi insiden, penyusunan laporan, penetapan tindakan korektif, verifikasi penyelesaian tindakan, hingga proses dokumentasi dan pengarsipan laporan.\",\"SOP ini menjadi acuan bagi seluruh unit kerja dalam melaksanakan pelaporan dan penanganan insiden secara konsisten sebagai bagian dari penerapan Sistem Manajemen SHE perusahaan.\"]','2026-07-25 10:30:38','2026-07-25 10:31:27');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2681','3232','referensi','[\"Kebijakan Keselamatan, Kesehatan Kerja, dan Lingkungan (SHE Policy) Perusahaan.\",\"Sistem Manajemen Keselamatan Pertambangan (SMKP) Minerba atau sistem manajemen keselamatan yang diterapkan perusahaan.\",\"Prosedur Investigasi Insiden dan Analisis Akar Penyebab (Root Cause Analysis).\",\"Peraturan perundang-undangan yang mengatur keselamatan dan kesehatan kerja serta keselamatan operasi pertambangan yang berlaku.\"]','2026-07-25 10:30:38','2026-07-25 10:31:57');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2682','3232','definisi','[\"Insiden adalah setiap kejadian yang tidak direncanakan selama aktivitas kerja yang mengakibatkan atau berpotensi mengakibatkan cedera pada pekerja, kerusakan aset perusahaan, gangguan operasional, pencemaran lingkungan, maupun kerugian lainnya. Insiden mencakup kecelakaan kerja, near miss, kerusakan peralatan, kebakaran, tumpahan material, serta kejadian lain yang memiliki dampak terhadap aspek keselamatan, kesehatan kerja, maupun lingkungan.\",\"Near Miss adalah kejadian yang tidak diinginkan tetapi tidak mengakibatkan cedera, kerusakan, ataupun kerugian karena masih dapat dihindari. Walaupun tidak menimbulkan dampak langsung, setiap Near Miss wajib dilaporkan karena dapat menjadi indikator adanya potensi bahaya yang memerlukan tindakan pengendalian agar tidak berkembang menjadi kecelakaan kerja.\",\"Investigasi insiden merupakan proses pengumpulan informasi, pemeriksaan fakta, wawancara, analisis data, dan identifikasi penyebab utama suatu insiden untuk mengetahui akar penyebab kejadian. Hasil investigasi digunakan sebagai dasar dalam menetapkan tindakan korektif dan tindakan pencegahan guna mengurangi kemungkinan terulangnya insiden serupa.\",\"Tindakan korektif adalah upaya yang dilakukan untuk menghilangkan penyebab suatu insiden yang telah terjadi, sedangkan tindakan pencegahan merupakan langkah yang diterapkan untuk mengurangi atau menghilangkan potensi terjadinya insiden pada masa mendatang. Kedua tindakan tersebut harus didokumentasikan, dipantau pelaksanaannya, dan diverifikasi efektivitasnya.\",\"Pelapor insiden adalah setiap pekerja, kontraktor, atau pihak lain yang mengetahui atau menyaksikan suatu insiden maupun kondisi berbahaya di lingkungan kerja. Pelapor berkewajiban memberikan informasi yang benar, lengkap, dan tepat waktu kepada atasan langsung atau Departemen SHE sesuai prosedur perusahaan.\"]','2026-07-25 10:30:38','2026-07-25 10:32:41');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2683','3232','aktivitas','[{\"sub_judul\":\"Pelaporan Awal Insiden\",\"deskripsi\":\"Pekerja yang mengalami atau menyaksikan insiden wajib segera melaporkan kejadian kepada atasan langsung atau SHE Officer sesegera mungkin setelah kondisi dinyatakan aman. Informasi yang disampaikan sekurang-kurangnya meliputi waktu kejadian, lokasi, jenis insiden, pihak yang terlibat, serta kondisi awal di lokasi kejadian.\",\"pic\":\"SHE Officer\"},{\"sub_judul\":\"Pengamanan Lokasi Kejadian\",\"deskripsi\":\"Supervisor bersama SHE Officer melakukan pengamanan lokasi insiden untuk mencegah bertambahnya korban maupun kerusakan. Area kejadian diberi pembatas, akses dibatasi hanya untuk personel yang berwenang, dan kondisi lokasi dipertahankan apabila diperlukan untuk proses investigasi.\",\"pic\":\"SHE Officer\"},{\"sub_judul\":\"Investigasi Insiden\",\"deskripsi\":\"Tim investigasi melakukan pengumpulan bukti, dokumentasi, wawancara saksi, pemeriksaan lokasi, serta analisis penyebab insiden menggunakan metode investigasi yang berlaku di perusahaan. Seluruh hasil investigasi dituangkan ke dalam laporan resmi sebagai dasar penentuan tindakan perbaikan.\",\"pic\":\"SHE Officer\"},{\"sub_judul\":\"Pendataan\",\"deskripsi\":\"Berdasarkan hasil investigasi, unit kerja terkait menyusun rencana tindakan korektif dan tindakan pencegahan untuk menghilangkan penyebab insiden. Seluruh tindakan harus memiliki penanggung jawab, target penyelesaian, serta dilakukan pemantauan hingga dinyatakan selesai.\",\"pic\":\"SHE Officer\"},{\"sub_judul\":\"Dokumentasi\",\"deskripsi\":\"Seluruh laporan insiden, hasil investigasi, tindakan korektif, dokumentasi pendukung, serta bukti penyelesaian diarsipkan oleh Departemen SHE sebagai bagian dari sistem manajemen perusahaan. Data insiden dievaluasi secara berkala untuk mengidentifikasi tren, mengevaluasi efektivitas pengendalian risiko, serta menjadi dasar peningkatan program keselamatan kerja.\",\"pic\":\"SHE\"}]','2026-07-25 10:32:56','2026-07-25 10:34:44');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2684','3232','lampiran','[{\"judul\":\"Pengecekan APD\",\"keterangan\":\"Proses pengecekan apd\",\"gambar\":\"lampiran\\/SHE\\/SOP\\/img_6a6420e392443.png\"}]','2026-07-25 10:32:56','2026-07-25 10:35:46');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2685','3233','analisa','[{\"langkah\":\"Persiapan pekerjaan dengan melakukan pengecekan area kerja, memastikan izin kerja telah diperoleh, serta menyiapkan APD dan peralatan yang diperlukan.\",\"bahaya\":[{\"risiko\":\"Area kerja licin atau tidak rapi sehingga berpotensi menyebabkan terpeleset atau tersandung.\",\"pengendalian\":[\"Pastikan area kerja bersih dan bebas hambatan.\",\"Bersihkan tumpahan air atau oli sebelum pekerjaan dimulai.\",\"Pasang rambu peringatan apabila terdapat potensi bahaya.\"]},{\"risiko\":\"Peralatan kerja tidak lengkap atau rusak sehingga menghambat pekerjaan.\",\"pengendalian\":[\"Periksa kelengkapan peralatan sebelum memulai pekerjaan dan pastikan mengganti peralatan yang rusak atau tidak layak pakai, sehingga akan di gunakan peralatan yang sesuai fungsi dan spesifikasinya\",\"Ganti peralatan yang rusak atau tidak layak pakai.\",\"Gunakan peralatan sesuai fungsi dan spesifikasinya.\"]},{\"risiko\":\"Tidak menggunakan APD yang sesuai.\",\"pengendalian\":[\"Gunakan APD sesuai ketentuan perusahaan.\"]}]},{\"langkah\":\"Melakukan pemeriksaan fisik perangkat komputer, laptop, printer, dan perangkat jaringan untuk memastikan kondisi perangkat dalam keadaan baik.\",\"bahaya\":[{\"risiko\":\"Sengatan listrik akibat perangkat masih terhubung ke sumber listrik.\",\"pengendalian\":[\"Matikan perangkat dan cabut sumber listrik sebelum pemeriksaan.\",\"Pastikan tangan dalam kondisi kering.\",\"Gunakan alat yang memiliki isolasi listrik.\"]},{\"risiko\":\"Terjepit atau tergores komponen perangkat.\",\"pengendalian\":[\"Gunakan alat kerja sesuai fungsi.\",\"Ikuti prosedur pembongkaran perangkat.\",\"Hindari menyentuh komponen sensitif secara langsung.\"]},{\"risiko\":\"Kerusakan perangkat akibat penanganan yang kurang tepat.\",\"pengendalian\":[\"Tangani perangkat dengan hati-hati sesuai prosedur.\"]}]},{\"langkah\":\"Melakukan pembersihan perangkat, update sistem operasi, aplikasi, antivirus, serta pemeriksaan performa perangkat.\",\"bahaya\":[{\"risiko\":\"Debu masuk ke saluran pernapasan.\",\"pengendalian\":[\"Gunakan masker saat membersihkan perangkat.\",\"Gunakan blower dengan tekanan yang sesuai.\",\"Bersihkan perangkat di area yang memiliki ventilasi baik.\"]},{\"risiko\":\"Kesalahan konfigurasi saat proses update.\",\"pengendalian\":[\"Lakukan backup data sebelum update.\"]},{\"risiko\":\"Kehilangan data akibat kegagalan pembaruan.\",\"pengendalian\":[\"Ikuti prosedur pembaruan sesuai standar ICT.\",\"Pastikan kapasitas penyimpanan mencukupi.\",\"Jangan mematikan perangkat selama proses update berlangsung.\"]}]},{\"langkah\":\"Melakukan pengujian perangkat, dokumentasi hasil pekerjaan, dan merapikan area kerja.\",\"bahaya\":[{\"risiko\":\"Perangkat tidak berfungsi setelah pemeliharaan.\",\"pengendalian\":[\"Lakukan functional test sebelum perangkat digunakan.\",\"Periksa kembali konfigurasi sistem.\",\"Pastikan seluruh kabel telah terpasang dengan benar.\",\"Dokumentasikan hasil pengujian.\"]},{\"risiko\":\"Area kerja tidak rapi sehingga membahayakan pengguna lain.\",\"pengendalian\":[\"Rapikan seluruh peralatan setelah pekerjaan selesai.\",\"Buang sampah pada tempatnya.\",\"Pastikan tidak ada kabel atau alat yang tertinggal di area kerja.\",\"Lakukan pemeriksaan akhir sebelum meninggalkan lokasi.\"]}]}]','2026-07-25 11:19:39','2026-07-25 11:19:39');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('2686','3233','apd','[\"Safety Helmet\",\"Safety Shoes\",\"Safety Glasses\",\"Sarung Tangan Kerja\",\"Rompi Safety\"]','2026-07-25 11:19:39','2026-07-25 11:19:39');
