INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('3681','3952','tujuan','[\"Menetapkan tata cara pelaksanaan proses handover perangkat, pekerjaan, maupun dokumen agar berjalan tertib, terdokumentasi, dan dapat dipertanggungjawabkan.\",\"Memastikan seluruh aset, informasi, dan tanggung jawab telah diserahkan secara lengkap kepada pihak penerima.\",\"Mencegah terjadinya kehilangan aset, informasi, maupun kesalahan operasional akibat proses serah terima yang tidak terdokumentasi.\",\"Mencegah terjadinya kehilangan aset, informasi, maupun kesalahan operasional akibat proses serah terima yang tidak terdokumentasi.\"]','2026-07-28 08:30:24','2026-07-28 08:30:49');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('3682','3952','ruang_lingkup','[\"SOP ini berlaku untuk seluruh proses handover perangkat IT, dokumen, akun sistem, dan pekerjaan yang dikelola oleh Departemen ICT.\",\"SOP ini diterapkan pada kegiatan serah terima antar personel, antar shift, maupun pada saat mutasi, cuti panjang, resign, atau pergantian PIC.\",\"SOP ini mencakup proses persiapan, pemeriksaan, verifikasi, dokumentasi, hingga persetujuan handover.\",\"SOP ini berlaku bagi seluruh karyawan, kontraktor, maupun pihak ketiga yang terlibat dalam proses handover\"]','2026-07-28 08:30:24','2026-07-28 08:31:15');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('3683','3952','referensi','[\"Kebijakan Pengelolaan Aset Teknologi Informasi PT PPA\",\"Standar Operasional Departemen ICT mengenai Manajemen Aset IT.\",\"Peraturan Perusahaan terkait Pengelolaan Dokumen dan Serah Terima Aset.\",\"ISO 9001:2015 \\u2013 Quality Management System.\",\"ISO\\/IEC 27001 \\u2013 Information Security Management System.\"]','2026-07-28 08:30:24','2026-07-28 08:31:49');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('3684','3952','definisi','[\"Handover adalah proses serah terima aset, dokumen, pekerjaan, atau tanggung jawab dari pihak pemberi kepada pihak penerima yang dibuktikan melalui dokumen resmi.\",\"Handover adalah proses serah terima aset, dokumen, pekerjaan, atau tanggung jawab dari pihak pemberi kepada pihak penerima yang dibuktikan melalui dokumen resmi.\",\"Penerima Handover adalah personel yang menerima aset, dokumen, pekerjaan, atau tanggung jawab serta bertanggung jawab atas pengelolaannya setelah proses serah terima selesai.\",\"Checklist Handover adalah daftar pemeriksaan yang digunakan untuk memastikan seluruh item yang diserahterimakan telah lengkap dan sesuai.\",\"Berita Acara Serah Terima (BAST) adalah dokumen resmi yang menjadi bukti telah dilaksanakannya proses handover antara kedua belah pihak\"]','2026-07-28 08:30:24','2026-07-28 08:32:17');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('3685','3952','aktivitas','[{\"sub_judul\":\"Persiapan Handover\",\"deskripsi\":\"Pemberi handover menyiapkan seluruh aset, dokumen, akun, serta informasi\\r\\npekerjaan yang akan diserahterimakan dan memastikan seluruh data telah\\r\\nlengkap.\",\"pic\":\"ICT\"},{\"sub_judul\":\"Pemeriksaan Kelengkapan\",\"deskripsi\":\"Melakukan pemeriksaan terhadap aset, dokumen, akun, lisensi, maupun\\r\\npekerjaan yang akan diserahterimakan berdasarkan checklist handover.\",\"pic\":\"Pemberi\\/Penerima Handover\"},{\"sub_judul\":\"Pelaksanaan Handover\",\"deskripsi\":\"Melaksanakan proses serah terima aset, pekerjaan, dan informasi kepada\\r\\npenerima serta memberikan penjelasan mengenai kondisi dan status\\r\\npekerjaan\",\"pic\":\"Pemberi Handover\"},{\"sub_judul\":\"Verifikasi Hasil Handover\",\"deskripsi\":\"Penerima melakukan verifikasi terhadap seluruh aset, dokumen, maupun\\r\\npekerjaan yang diterima untuk memastikan kesesuaian dengan checklist\\r\\nhandover\",\"pic\":\"Penerima Handover\"},{\"sub_judul\":\"Dokumentasi dan Persetujuan\",\"deskripsi\":\"Mengisi Berita Acara Serah Terima (BAST), memperoleh tanda tangan pihak\\r\\nterkait, serta mengarsipkan dokumen handover sebagai bukti administrasi\",\"pic\":\"ICT\"},{\"sub_judul\":\"Penutupan Proses\",\"deskripsi\":\"Melakukan pembaruan data inventaris, penyesuaian hak akses apabila diperlukan, serta menyatakan proses handover telah selesaI\",\"pic\":\"ICT\"}]','2026-07-28 08:32:26','2026-07-28 08:35:38');
INSERT INTO `document_contents` (`id`,`document_id`,`section_key`,`value_json`,`created_at`,`updated_at`) VALUES ('3686','3952','lampiran','[{\"judul\":\"Form Checklist\",\"keterangan\":\"Daftar pemeriksaan yang digunakan untuk memastikan seluruh aset, dokumen, akun, dan pekerjaan\\r\\ntelah diserahterimakan secara lengkap.\",\"gambar\":null},{\"judul\":\"Berita Acara Serah Terima\",\"keterangan\":\"Dokumen resmi yang berisi informasi proses handover serta ditandatangani oleh pemberi, penerima, dan pihak yang berwenang sebagai bukti serah terima.\",\"gambar\":null},{\"judul\":\"Testing Foto\",\"keterangan\":\"LOGO SMARTPRO\",\"gambar\":\"lampiran\\/ICTMD\\/SOP\\/img_6a67f9a2bebf6.png\"}]','2026-07-28 08:32:26','2026-07-28 08:36:52');
